 29→export const loader = async ({ request }: LoaderFunctionArgs) => {
 30→  const { session } = await authenticate.admin(request);
 31→  const shop = session.shop;
 32→
 33→  const [charts, subscription] = await Promise.all([
 34→    db.sizeChart.findMany({
 35→      where: { shop },
 36→      orderBy: { updatedAt: "desc" },
 37→      include: { assignments: true },
 38→    }),
 39→    db.subscription.findUnique({ where: { shop } }),
 40→  ]);
 41→
 42→  const plan = getPlan(subscription?.planId ?? "free");
 43→  const templates = SIZE_CHART_TEMPLATES.map((t) => ({
 44→    name: t.name,
 45→    category: t.category,
 46→    gender: t.gender,
 47→    rowCount: t.data.rows.length,
 48→  }));
 49→  const categories = getCategories();
 50→
 51→  return {
 52→    charts,
 53→    plan,
 54→    templates,
 55→    categories,
 56→    canCreate: canCreateChart(plan.id, charts.length),
 57→  };
 58→};
